<?php
declare(strict_types=1);
require_once __DIR__.'/../devis/includes/module_bootstrap.php';
require_once __DIR__.'/../services/ChantierDashboardReport.php';
AccessManager::requirePageAccess('liste_chantier.php');
$scope=$_GET['scope']??'active';if(!in_array($scope,['active','archived','all'],true)){http_response_code(400);exit('Périmètre invalide.');}
$rows=ChantierDashboardReport::rows(Database::getConnection(),$scope);$t=ChantierDashboardReport::totals($rows);
$activeDevisModule='chantiers';$moduleTitle='Pilotage des chantiers';$moduleSubtitle='Suivi des dossiers opérationnels, des budgets prévisionnels et de la conformité financière.';
$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$url=static fn($p)=>htmlspecialchars(devis_module_root_url($p),ENT_QUOTES,'UTF-8');
$money=static fn($v)=>number_format((float)$v,0,',',' ').' FCFA';
$clients=[];foreach($rows as $r){$name=$r['nom_client']?:'Client non renseigné';$clients[$name]=($clients[$name]??0)+1;}arsort($clients);$clients=array_slice($clients,0,8,true);
ob_start();
?>
<div class="site-workspace">
<nav class="ed-tabs" aria-label="Périmètre"><?php foreach(['active'=>'Non archivés','archived'=>'Archives','all'=>'Tous'] as $key=>$label):?><a class="<?=$scope===$key?'active':''?>" href="<?=$url('chantiers/dashboard.php?scope='.$key)?>"><?=$e($label)?></a><?php endforeach;?></nav>
<section class="ed-kpis"><?php foreach([['Chantiers',$t['count'],'fa-helmet-safety','Périmètre sélectionné'],['Dossiers conformes',$t['compliant'],'fa-circle-check','Conformité financière'],['Valeur des devis TTC',$money($t['contract']),'fa-file-contract','Devis distincts'],['Déboursés prévus',$money($t['budget']),'fa-wallet','Budget prévisionnel, non payé']] as $k):?><article class="ed-kpi"><div class="ed-kpi-icon"><i class="fa-solid <?=$k[2]?>"></i></div><span><?=$e($k[0])?></span><strong><?=$e($k[1])?></strong><small><?=$e($k[3])?></small></article><?php endforeach;?></section>
<section class="ed-grid"><article class="ed-panel"><h2>Accès rapides</h2><p>Gestion et suivi des dossiers de chantier.</p><div class="ed-actions"><a class="primary" href="<?=$url('chantiers/choisir_devis.php')?>"><i class="fa-solid fa-plus"></i> Nouveau chantier</a><a href="<?=$url('chantiers/liste.php')?>"><i class="fa-solid fa-list"></i> Liste des chantiers</a><a href="<?=$url('chantiers/liste.php?archives=1')?>"><i class="fa-solid fa-box-archive"></i> Archives</a><a href="<?=$url('chantiers/regularisation.php')?>"><i class="fa-solid fa-screwdriver-wrench"></i> Régularisation</a><a href="<?=$url('chantiers/parametrage.php')?>"><i class="fa-solid fa-sliders"></i> Paramétrage</a></div><div class="ed-export"><?php foreach(['pdf'=>'PDF','xlsx'=>'Excel'] as $f=>$label):?><a href="<?=$url('exports/finea_module_export.php?module=chantiers&format='.$f.'&scope='.$scope)?>"><i class="fa-solid <?=$f==='pdf'?'fa-file-pdf':'fa-file-excel'?>"></i> Export <?=$label?></a><?php endforeach;?></div></article>
<article class="ed-panel"><h2>Contrôles opérationnels</h2><p>Indicateurs de vigilance sur le périmètre sélectionné.</p><div class="ed-list"><?php foreach([['Dossiers non conformes ou non évalués',$t['count']-$t['compliant']],['Sans déboursé rattaché',$t['missing']],['Chantiers suspendus non archivés',$t['paused']]] as $k):?><div class="ed-list-item"><strong><?=$e($k[0])?></strong><span class="ed-pill"><?=$k[1]?></span></div><?php endforeach;?></div><div class="ed-note">Les montants TTC et les déboursés prévisionnels ne constituent pas une mesure de marge ni de trésorerie.</div></article></section>
<section class="ed-grid"><article class="ed-panel"><h2>Répartition par client</h2><div class="ed-bars"><?php foreach($clients as $name=>$n):?><div><div class="ed-bar-head"><span><?=$e($name)?></span><strong><?=$n?></strong></div><div class="ed-track"><div class="ed-fill" style="width:<?=100*$n/max(1,$t['count'])?>%"></div></div></div><?php endforeach;?><?php if(!$clients):?><p>Aucun chantier enregistré.</p><?php endif;?></div></article><article class="ed-panel"><h2>Derniers dossiers</h2><div class="ed-list"><?php foreach(array_slice($rows,0,6) as $r):?><div class="ed-list-item"><div><strong><?=$e($r['titre'])?></strong><small><?=$e($r['code'].' · '.($r['nom_client']??'Client non renseigné'))?></small><small><?=$e(ChantierDashboardReport::state($r))?></small></div><a class="ed-pill" href="<?=$url('chantiers/details.php?id='.(int)$r['id'])?>">Détails</a></div><?php endforeach;?><?php if(!$rows):?><p>Aucun dossier dans ce périmètre.</p><?php endif;?></div></article></section></div>
